import numpy as np
def equation(eps, T, params):
    p = params
    a = p[0] + p[1]*T + p[2]/T
    Q = p[3] + p[4]*T + p[5]/T
    return a + Q*np.exp(-p[6]*eps) + p[7]*eps + p[8]*eps**3 + p[9]*np.log(eps)
